 // Raised menus cover text beneath them; keep the shared card fill opaque.
 Brush TaskSectionFill(){if(SystemParameters.HighContrast){var color=SystemColors.HighlightColor;color.A=255;return new SolidColorBrush(color);}return BrushColor(prefs.Theme=="light"?"#E4E6E5":"#414343");}
 void RotateTaskChevron(ComboBox lists,bool expanded){var arrow=lists.Template.FindName("TaskListChevron",lists) as FrameworkElement;if(arrow==null)return;double target=expanded?180:0;var rotate=new RotateTransform(target);arrow.RenderTransform=rotate;if(MotionAllowed)rotate.BeginAnimation(RotateTransform.AngleProperty,new DoubleAnimation(expanded?0:180,target,TimeSpan.FromMilliseconds(130)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});}
 void StyleTaskPopup(ComboBox lists){
  var popup=(Popup)lists.Template.FindName("PART_Popup",lists);var frame=popup.Child as Border;if(frame==null)return;
  RotateTaskChevron(lists,true);frame.Opacity=0;frame.Background=TaskSectionFill();frame.Clip=null;frame.ClipToBounds=false;frame.Effect=TaskSectionShadow();
  var raised=lists.Template.FindName("TaskListRaisedSection",lists) as Border;if(raised==null)return;
  raised.Opacity=0;raised.Background=frame.Background;raised.Effect=TaskSectionShadow();raised.RenderTransform=new TranslateTransform(0,-3);raised.Clip=null;
  var body=frame.Child as FrameworkElement;if(body!=null)body.RenderTransform=Transform.Identity;
  int generation=frame.Tag is int?(int)frame.Tag+1:1;frame.Tag=generation;
  // The popup must finish its native placement while invisible. Both surfaces
  // then become visible with identical clips driven by the same animation clock.
  lists.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,new Action(()=>{
   if(!popup.IsOpen||!Equals(frame.Tag,generation))return;
   frame.UpdateLayout();raised.UpdateLayout();AlignTaskPopup(frame,raised);
   if(MotionAllowed){var title=(FrameworkElement)lists.Template.FindName("TaskListTitle",lists);double start=Math.Min(raised.Width,title.ActualWidth+32);AnimateTaskSectionsTogether(raised,frame,start,raised.Width);}
   raised.Opacity=frame.Opacity=1;
  }));
 }
 void AnimateTaskSectionsTogether(Border upper,Border lower,double start,double end){
  var from=new Rect(-16,-16,start+32,8192);var to=new Rect(-16,-16,end+32,8192);var topClip=new RectangleGeometry(from);var bottomClip=new RectangleGeometry(from);upper.Clip=topClip;lower.Clip=bottomClip;
  var animation=new RectAnimation(from,to,TimeSpan.FromMilliseconds(160)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}};var clock=animation.CreateClock();clock.Completed+=delegate{if(ReferenceEquals(upper.Clip,topClip))upper.Clip=null;if(ReferenceEquals(lower.Clip,bottomClip))lower.Clip=null;};topClip.ApplyAnimationClock(RectangleGeometry.RectProperty,clock);bottomClip.ApplyAnimationClock(RectangleGeometry.RectProperty,clock);
 }
 void AlignTaskPopup(Border frame,Border raised){
  var source=PresentationSource.FromVisual(frame) as HwndSource;if(source==null)return;NativeRect bounds;if(!GetWindowRect(source.Handle,out bounds))return;
  var actual=frame.PointToScreen(new Point(0,0));var desired=raised.PointToScreen(new Point(0,raised.ActualHeight));int dx=(int)Math.Round(desired.X-actual.X),dy=(int)Math.Round(desired.Y-actual.Y);
  if(dx!=0||dy!=0)Native.Position(source.Handle,new System.Drawing.Rectangle(bounds.Left+dx,bounds.Top+dy,bounds.Right-bounds.Left,bounds.Bottom-bounds.Top));
 }
 System.Windows.Media.Effects.DropShadowEffect TaskSectionShadow(){return new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=20,ShadowDepth=0,Opacity=.3,Color=Colors.Black};}
 void AttachDialogDrag(Grid caption,Window window){caption.PreviewMouseLeftButtonDown+=delegate(object sender,System.Windows.Input.MouseButtonEventArgs e){DependencyObject node=e.OriginalSource as DependencyObject;while(node!=null&&node!=caption){if(node is ButtonBase||node is TextBoxBase||node is Selector)return;node=node is Visual?VisualTreeHelper.GetParent(node):LogicalTreeHelper.GetParent(node);}if(node!=caption)return;try{window.DragMove();e.Handled=true;}catch(InvalidOperationException){}};}
